  if (s.includes('class="t"')) continue;
  const m = s.match(/<(rect|circle|ellipse)\b(?![^>]*class=)[^>]*\/>|<path\b(?![^>]*class=)[^>]*\bd="[^"]*[zZ]"[^>]*\/>/);
